import {S,term as T,step as P,check as Q,task as A,lesson as L} from './shared.js';
export default [
L(11,1,{
 title:'提出一个能回答的研究问题',summary:'以“输入噪声能否改善长期预测”为例，把模糊想法变成假设、变量、指标和否定条件。',prerequisites:['w8-l3','w4-l1'],
 terms:[T('研究问题','一项需要通过证据回答的具体问题。','在固定训练预算下，输入扰动是否改善 20 步自由预测误差？'),T('假设 hypothesis','对结果和可能原因的可检验预测。','适量噪声可能让模型更适应自由运行中不完美的输入。'),T('主指标 primary metric','提前指定用来判断主要目标的指标。','本例为独立轨迹上的 20 步 rollout MSE。'),T('否定条件','哪些观察会让你放弃或修正假设。','多个种子上长期误差不改善，或提升只来自更大预算。')],
 sections:[P('第 1 步：从一个具体失败出发','先查看基线的真实历史误差与自由运行误差。若一步很好、长预测漂移，输入分布差异是一个候选解释。不要看到“输入噪声”是流行技巧就先加上再找理由。','其他解释也可能成立：动作未被利用、状态信息不足、损失权重不合适。把它们列为竞争解释，避免把一个猜测当作已经证实的机制。'),P('第 2 步：定义唯一主要改动','候选改动为训练时对输入状态增加零均值扰动，预测目标仍是干净下一状态。必须写明噪声尺度、在哪个空间施加、哪些位置生效、训练和评测是否都施加。','像素噪声与 latent 噪声不是同一种干预；模型输入归一化不同，相同数值的标准差也可能代表不同强度。先检查实际尺度，再设参数范围。'),P('第 3 步：提前确定评价规则','主指标采用固定独立轨迹、固定 horizon 的自由运行误差；辅指标包括单步误差、动作打乱对照、吞吐与资源。规定总步数或有效样本预算，选择模型只使用验证集。','如果主指标改善但单步误差明显恶化，结论应描述权衡。不能在结果出来后挑唯一上涨的指标当作本来的主要目标。'),P('第 4 步：先做小预算试验','先用很小预算检查噪声确实生效、目标保持干净、评测没有意外增加噪声，以及模型没有崩溃。通过后再进行正式对照。','这个试验是流程检查，不用于宣布最终优劣。最终报告保留失败试验，解释它们为何帮助缩小问题范围。')],
 worked:{title:'把“加点噪声试试”改写成实验卡',steps:['问题：基线在 20 步自由运行中漂移。','改动：只在训练输入的归一化状态上加标准差 0.02 的零均值噪声。','固定：数据划分、初始权重、更新预算和评测协议。','预期：独立轨迹长期误差下降；否定条件：重复试验没有稳定收益或动作响应退化。'],takeaway:'一个好问题必须能告诉你该改什么、看什么以及何时承认没改善。'},
 example:{code:'experiment = {"variable": "input_noise_std", "baseline": 0.0, "variant": 0.02,\n              "primary_metric": "rollout_mse_h20", "train_steps": 300,\n              "validation_protocol": "fixed independent episodes"}\nfor key,value in experiment.items():\n    print(key, value)',output:'variable input_noise_std\nbaseline 0.0\nvariant 0.02\nprimary_metric rollout_mse_h20\ntrain_steps 300\nvalidation_protocol fixed independent episodes',explanation:'这是待执行的实验规范，不是已经获得收益的结果。'},
 checks:[Q('为什么要在运行前确定主指标？','如果事后从很多分数中挑上涨的那一个会怎样？','可以减少选择性解释，使假设有明确的成败判断条件。',2),Q('像素上标准差 0.02 与 latent 上 0.02 的噪声效果必然相同吗？','两个空间的尺度和含义一样吗？','不相同。需记录空间、归一化与实际扰动尺度。',1)],
 practice:{title:'写好一份还没有结果的实验卡',steps:[A('从世界模型基线挑一个具体失败样例。','说明失败发生的状态、动作和预测长度。','不要用“效果一般”作为问题定义。'),A('写假设、主要变量、固定项、主辅指标和否定条件。','可以在运行前判断什么结果算支持假设。','如果同时改三种技巧，先拆成可以解释的对照。'),A('使用实验手记模板，保持结果栏为空直到实际运行。','清楚区分计划与观察。','课程给的数值只是演示，不能写成自己的训练成绩。')]},links:[{label:'实验手记',href:'#/notebook'}],sources:[S.cs336,S.repro]
}),
L(11,2,{
 title:'控制变量与消融：怎样让比较有解释力',summary:'用一张小型实验矩阵检查预算与随机性，学会比较方法而不是比较两次偶然运行。',prerequisites:['w11-l1','w4-l2'],
 terms:[T('消融 ablation','移除或改变某个组件，检查它对结果的贡献。','分别关闭输入噪声、动作输入或记忆，观察对应变化。'),T('控制变量','让无关因素尽量一致，以便解释所研究的变化。','固定数据划分、评测样本和训练预算。'),T('重复种子','使用不同随机种子重复实验，观察对随机性的敏感程度。','一次提升不能代替重复结果的分布。'),T('公平预算','明确按照何种资源或数据量对齐比较。','同 step、同 token、同 GPU 时间是不同约束。')],
 sections:[P('第 1 步：画出最小实验矩阵','先选基线和一个变体，各使用相同的三个种子。其他设置保持一致，分别记录每次主指标。先有明确对照，再增加更多强度或组件。','种子编号相同有助于配对控制，但不同实现对随机数的消费可能不同。报告具体初始化与数据顺序策略，不能仅凭 seed 相同声称一切随机性完全一致。'),P('第 2 步：把预算换算成可比较的量','batch=16、训练 1000 步，与 batch=32、训练 1000 步，通常看到的样本量不同。增加分辨率、序列长度或采样步数也会改变计算预算。','明确你回答的是“同更新次数下哪种更好”“同数据量下哪种更好”还是“同时间预算下哪种更好”。结论只能对应所采用的口径。'),P('第 3 步：理解固定配置与各自调优','完全固定学习率可以隔离一个改动，但可能偏向更适合该学习率的方法。允许两种方法分别调优，则更接近实际最佳可达表现，却需要额外说明搜索空间和预算。','两类比较都可以做，不能把其中一种叫作唯一公平。先写实验目的，再选择比较协议，并防止只给新方法更多调参机会。'),P('第 4 步：报告平均与波动','列出每个种子的结果、平均值和波动。只有三个种子时，统计仍然有限，不要把一个很小的平均差异包装成普遍规律。','如果在某些轨迹改善、另一些恶化，继续按场景分组。总体平均和错误类型一起看，才能决定下一轮实验。')],
 worked:{title:'一份可以读懂的重复实验表',steps:['基线三次误差：[0.10,0.12,0.11]，平均 0.11。','变体：[0.09,0.13,0.10]，平均约 0.1067。','平均略好，但第二次更差，整体波动与改进幅度接近。','先保留谨慎结论，增加证据或分析场景，而不是只展示 0.09。'],takeaway:'重复实验的目的不是凑一个好结果，而是发现结论有多稳定。'},
 example:{code:'from statistics import mean, stdev\nbaseline = [0.10, 0.12, 0.11]\nvariant = [0.09, 0.13, 0.10]\nfor name, values in [("base",baseline),("variant",variant)]:\n    print(name, round(mean(values), 4), round(stdev(values), 4))',output:'base 0.11 0.01\nvariant 0.1067 0.0208',explanation:'这里报告样本标准差，不是置信区间，也没有进行显著性检验。不能把它们混为同一种统计结论。'},
 checks:[Q('两次都训练 1000 step，是否必然公平？','比较每步消费的数据与计算量。','不必然。batch、长度、分辨率或模型规模不同会改变预算，需要明确对齐口径。',1),Q('只展示最好的随机种子有什么问题？','读者会怎样理解结果稳定性？','会隐瞒波动和失败，使效果看起来更稳定；应报告预先约定的全部重复。',3)],
 practice:{title:'在开跑前审查实验矩阵',steps:[A('给基线和变体各列相同的种子及预算。','每一行是一项独立、可复现的运行。','不要运行到某次特别好就提前停止。'),A('检查样本量、有效目标、计算时间是否混用。','选定主预算，其他预算也记录。','“同样一张 GPU”不能单独说明预算一致。'),A('运行小规模对照，记录所有结果和失败运行。','结论与实际观察范围一致。','变体没赢也保留记录，分析为何不支持假设。')]},sources:[S.repro,S.cs336]
}),
L(11,3,{
 title:'从日志到结论：区分事实、解释与下一步',summary:'把一次实验写成别人能复核的报告，特别追踪 loss 分母、数据消费与失败模式。',prerequisites:['w11-l2','w9-l3'],
 terms:[T('观测事实','直接由日志、评测或样本得到的结果。','固定验证集上的 20 步误差从 0.10 变为 0.09。'),T('机制解释','用来解释结果为何发生的假设。','“改善来自更好的输入鲁棒性”还需要进一步对照支持。'),T('数据账本','记录本次实际使用的数据版本、切分、采样及消费量。','原始池有多少与本次训练看了多少分别记录。'),T('失败分类','按可操作的原因或场景整理错误。','长跨度漂移、动作反应不足、遮挡和接触失败。')],
 sections:[P('第 1 步：先保留原始证据','保存命令、提交版本、有效配置、数据版本、运行环境、seed、检查点来源、日志和评测输出。用独立实验目录，避免只保留终端截图。','报告里的每个数字都应能找到对应文件或计算方法。如果没有实际运行，不应把课程演示数值或他人的结果放进“本次结果”栏。'),P('第 2 步：解释 loss 的计算定义','日志可能都叫 train_loss，但一种是每 token 平均，另一种是每样本平均；一种只计回答，另一种包括全部输入。先追踪分子、分母、mask 与跨设备汇总方式。','相同名称的不同量不能直接比较。即使公式相同，数据长度和构成变化也会影响数值；需要独立固定评测提供参照。'),P('第 3 步：把观察与原因分开写','第一句写发生了什么，并注明协议。第二句提出可能解释。第三句说明证据尚不能排除的其他原因。最后设计一个能够区分这些解释的下一步实验。','例如长期误差改善，可能来自输入鲁棒性，也可能来自正则化或偶然种子差异。只凭一项分数不能唯一识别原因。'),P('第 4 步：让失败样例决定下一轮','对失败按场景、动作、预测长度和初始状态分组。找共同特征，检查是否与数据覆盖、观测信息或模型接口有关。优先修复能形成明确证据链的问题。','古琴项目也可以复用这种方法：逐音匹配、可演奏性、指法切换与风格是不同维度；先明确哪种失败最影响目标，再决定新增标注还是修改建模。')],
 worked:{title:'把一句过强结论改写为可复核结论',steps:['过强：“加噪让世界模型理解了物理。”','事实：“在固定 32 条验证轨迹、20 步自由预测下，平均误差降低。”','解释：“结果与输入鲁棒性改善相符，但尚不能排除其他正则效果。”','下一步：“增加不同扰动强度、种子和动作响应对照，检查收益边界。”'],takeaway:'解释可以大胆提出，但证据范围必须诚实标明。'},
 example:{code:'report = {"observed": "rollout error decreased on fixed validation episodes",\n          "hypothesis": "better robustness to imperfect history",\n          "unresolved": "seed variability and alternative regularization effects",\n          "next": "repeat seeds and compare noise strengths"}\nprint("sections", list(report.keys()))',output:"sections ['observed', 'hypothesis', 'unresolved', 'next']",explanation:'这是报告结构示意，不表示本课程已经替你验证输入噪声一定有效。'},
 checks:[Q('日志里都叫 loss，就能直接横向比较吗？','检查监督范围、分母和数据。','不能。需要先核对计算定义、归一化、掩码和评测协议。',1),Q('分数提高可以直接证明某个机制解释吗？','是否还存在其他能产生同样结果的原因？','通常不能。要通过有辨别力的控制实验排除竞争解释。',2)],
 practice:{title:'提交你的第一份算法实验报告',steps:[A('整理实验卡、命令、数据账本和逐运行结果。','关键数字有可追溯来源。','缺少字段时标为未知，不事后编造。'),A('选三类失败样例并写出可检验原因。','每个原因对应下一步检查或实验。','不要只展示最好看的例子。'),A('写“事实、解释、限制、下一步”四段。','未验证的解释不会伪装成确定结论。','报告允许结论为“未观察到稳定改善”。')]},links:[{label:'记录与导出实验报告',href:'#/notebook'}],sources:[S.repro,S.cs336]
})];
